const supportedLanguages = new Set(Object.keys(translations));
let currentLanguage = "pl";
function normalizeLanguage(value) { const language = String(value ?? "").trim().toLowerCase().split("-")[0]; return supportedLanguages.has(language) ? language : null; }
export function detectLanguage() { let stored = null; try { stored = normalizeLanguage(window.localStorage.getItem("qpcr-ui-language")); } catch {} if (stored) return stored; for (const language of navigator.languages ?? [navigator.language]) { const normalized = normalizeLanguage(language); if (normalized) return normalized; } return "pl"; }
export function getLanguage() { return currentLanguage; }
export function setLanguage(value, { persist = true } = {}) { currentLanguage = normalizeLanguage(value) ?? "pl"; document.documentElement.lang = currentLanguage; if (persist) { try { window.localStorage.setItem("qpcr-ui-language", currentLanguage); } catch {} } return currentLanguage; }
export function t(key, parameters = {}, fallback = key) { const template = translations[currentLanguage]?.[key] ?? translations.en[key] ?? fallback; return String(template).replace(/\{([A-Za-z0-9_]+)\}/g, (match, name) => parameters[name] ?? match); }
export function translateEnum(value) { const normalized = String(value ?? "").trim(); return normalized ? t(`enum.${normalized.toLowerCase()}`, {}, normalized.replaceAll("_", " ")) : ""; }
export function applyStaticTranslations(root = document) { document.title = t("app.title"); root.querySelectorAll("[data-i18n]").forEach((element) => { element.textContent = t(element.dataset.i18n); }); root.querySelectorAll("[data-i18n-aria-label]").forEach((element) => { element.setAttribute("aria-label", t(element.dataset.i18nAriaLabel)); }); root.querySelectorAll("[data-i18n-placeholder]").forEach((element) => { element.setAttribute("placeholder", t(element.dataset.i18nPlaceholder)); }); }
export function numberLocale() { return currentLanguage === "pl" ? "pl-PL" : "en-US"; }
